-- Ada Health — Здоров'я та краса / Медицина
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`, `created_by`) SELECT 'Ada Health', NULL, 'https://ada.com', NULL, NULL, 'Безкоштовний застосунок, що ставить запитання про самопочуття й формує звіт із можливими причинами симптомів для подальшої розмови з лікарем.', NULL, 'Ada Health — застосунок, сертифікований як медичний пристрій у ЄС, що проводить структуроване опитування про самопочуття й порівнює відповіді з базою медичних станів, формуючи звіт для користувача. Розробники прямо зазначають, що застосунок не замінює діагноз лікаря, а лише допомагає підготуватись до візиту. Доступний 24/7, декількома мовами.', NULL, 'Структуроване опитування про самопочуття
Формування звіту з можливими причинами
Збереження історії звітів для показу лікарю
Доступність 24/7 кількома мовами', NULL, 'Будь-хто, хто хоче підготуватись до розмови з лікарем чи краще зрозуміти власне самопочуття', NULL, 'web,mobile', 'none', 'published', '0', 'no_partnership', '2026-09-03 22:01:00', (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'ada.com' OR LOWER(`name`) = LOWER('Ada Health')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'ada.com' OR LOWER(`name`) = LOWER('Ada Health')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND (c.`slug` = 'health-beauty' OR c.`name` = 'Здоров''я та краса') ORDER BY c.`slug` = 'health-beauty' DESC LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND (c.`slug` = 'health-beauty' OR c.`name` = 'Здоров''я та краса') AND (s.`slug` = 'medicine' OR s.`name` = 'Медицина') ORDER BY s.`slug` = 'medicine' DESC LIMIT 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Free', NULL, 0.00, 'free', 'повний доступ до опитування й звітів', NULL FROM DUAL WHERE @new = 1;

-- Google Health — Здоров'я та краса / Спорт та фітнес
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`, `created_by`) SELECT 'Google Health', NULL, 'https://health.google', NULL, NULL, 'Об''єднує дані про активність, сон і тренування з різних застосунків і пристроїв в одному місці, з базовим AI-помічником для фітнес-планів.', NULL, 'Google Health (раніше Google Fit) збирає дані про кроки, тренування, сон та інші показники з різних сумісних застосунків і пристроїв в одну картину. Безкоштовна версія показує базову активність, платна версія додає AI-помічника, що будує й коригує персональний фітнес-план.', NULL, 'Об''єднує дані активності з різних застосунків і пристроїв
Відстежує кроки, тренування, сон
AI-помічник для персонального фітнес-плану (платна версія)
Спільні рейтинги з друзями', NULL, 'Будь-хто, хто хоче зібрати фітнес-дані з різних джерел в одному місці', NULL, 'mobile', 'none', 'published', '0', 'no_partnership', '2026-09-03 22:01:00', (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'health.google' OR LOWER(`name`) = LOWER('Google Health')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'health.google' OR LOWER(`name`) = LOWER('Google Health')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND (c.`slug` = 'health-beauty' OR c.`name` = 'Здоров''я та краса') ORDER BY c.`slug` = 'health-beauty' DESC LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND (c.`slug` = 'health-beauty' OR c.`name` = 'Здоров''я та краса') AND (s.`slug` = 'sports-fitness' OR s.`name` = 'Спорт та фітнес') ORDER BY s.`slug` = 'sports-fitness' DESC LIMIT 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Free', NULL, 0.00, 'free', 'базове відстеження активності', NULL FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Premium', NULL, 0.00, 'one_time', 'ціна окремо, розширений AI-коучинг (продається окремо від базового застосунку)', NULL FROM DUAL WHERE @new = 1;

-- Apple Health — Здоров'я та краса / Медицина, Здоров'я та краса / Спорт та фітнес
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`, `created_by`) SELECT 'Apple Health', NULL, 'https://apple.com/health', NULL, NULL, 'Вбудований застосунок для iPhone, що збирає дані про активність, сон, харчування й показники здоров''я в одному місці.', NULL, 'Apple Health — вбудований застосунок на iPhone, що об''єднує дані про активність, сон, харчування та інші показники з Apple Watch і сумісних сторонніх застосунків. Показує тренди з часом і дозволяє ділитись обраними даними з лікарем чи членами родини.', NULL, 'Об''єднує дані активності, сну й харчування
