-- Deepgram — Переклад та мови / Розпізнавання мови
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`, `created_by`) SELECT 'Deepgram', NULL, 'https://deepgram.com', NULL, NULL, 'AI-платформа розпізнавання й синтезу мовлення (Speech-to-Text, Text-to-Speech) для розробників — модель Nova-3, висока точність і швидкість у реальному часі.', NULL, 'Deepgram надає API для перетворення мовлення в текст і синтезу мовлення, побудоване на власних end-to-end deep learning моделях (Nova-3). Підтримує розпізнавання в реальному часі та пакетну обробку, діаризацію спікерів, розпізнавання ключових слів і роботу з галасливим аудіо.', NULL, 'Розпізнавання мовлення в реальному часі та пакетна обробка
