INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND (c.`slug` = 'productivity' OR c.`name` = 'Продуктивність') ORDER BY c.`slug` = 'productivity' DESC LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND (c.`slug` = 'productivity' OR c.`name` = 'Продуктивність') AND (s.`slug` = 'planning' OR s.`name` = 'Планування') ORDER BY s.`slug` = 'planning' DESC LIMIT 1;

